let mobileMenuButton=document.querySelector(".mobile-menu-button"),mobileMenu=document.querySelector(".mobile-menu");mobileMenuButton.addEventListener("click",()=>{mobileMenu.classList.toggle("hidden")}),document.querySelectorAll('a[href^="#"]').forEach(e=>{e.addEventListener("click",function(e){e.preventDefault();e=this.getAttribute("href"),e=document.querySelector(e);e&&(window.scrollTo({top:e.offsetTop-80,behavior:"smooth"}),mobileMenu.classList.contains("hidden")||mobileMenu.classList.add("hidden"))})});